-- Simula la base que ya existe: columnas del listado + restricciones y RLS del plan técnico.
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role text not null default 'QA', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.daily_groups (id bigint generated by default as identity primary key, code text not null unique, name text not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.daily_members (id bigint generated by default as identity primary key, daily_group_id bigint not null references public.daily_groups(id) on delete cascade, name text not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(daily_group_id, name));
create table public.daily_rules (id bigint generated by default as identity primary key, daily_group_id bigint not null unique references public.daily_groups(id) on delete cascade, first_range integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.daily_rule_members (id bigint generated by default as identity primary key, daily_member_id bigint not null unique references public.daily_members(id) on delete cascade, rule_type text not null check (rule_type in ('FIRST_GROUP','LAST_FIXED')), created_at timestamptz not null default now());
create table public.projects (id bigint generated by default as identity primary key, code text not null unique, name text not null, color text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.project_variants (id bigint generated by default as identity primary key, project_id bigint not null references public.projects(id) on delete cascade, name text not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(project_id, name));
create table public.templates (id bigint generated by default as identity primary key, project_id bigint not null references public.projects(id) on delete cascade, variant_id bigint references public.project_variants(id) on delete cascade, active boolean not null default true, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.template_tasks (id bigint generated by default as identity primary key, template_id bigint not null references public.templates(id) on delete cascade, position integer not null, task text not null, created_at timestamptz not null default now(), unique(template_id, position));
create table public.qa_generations (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id), project_id bigint references public.projects(id), variant_id bigint references public.project_variants(id), created_at timestamptz not null default now());
create table public.qa_generation_items (id bigint generated by default as identity primary key, generation_id bigint not null references public.qa_generations(id) on delete cascade, pbi_number text, pbi_text text not null, created_at timestamptz not null default now());
create table public.qa_generation_tasks (id bigint generated by default as identity primary key, generation_item_id bigint not null references public.qa_generation_items(id) on delete cascade, position integer not null, task text not null, created_at timestamptz not null default now());
create table public.daily_runs (id bigint generated by default as identity primary key, daily_group_id bigint not null references public.daily_groups(id), created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.daily_run_members (id bigint generated by default as identity primary key, daily_run_id bigint not null references public.daily_runs(id) on delete cascade, daily_member_id bigint references public.daily_members(id), member_name text not null, position integer not null, completed boolean not null default false, created_at timestamptz not null default now());
create table public.ai_usage_log (id bigint generated by default as identity primary key, user_id uuid references auth.users(id), action text not null, success boolean not null default true, created_at timestamptz not null default now());

create or replace function public.current_user_role() returns text language sql stable security definer set search_path = public as $$ select role from public.profiles where id = auth.uid(); $$;
alter table public.profiles enable row level security;
alter table public.projects enable row level security;
alter table public.daily_members enable row level security;
alter table public.qa_generations enable row level security;
create policy "profiles_select_own" on public.profiles for select to authenticated using (id = auth.uid());
create policy "daily_members_authenticated_read" on public.daily_members for select to authenticated using (true);
create policy "projects_authenticated_read" on public.projects for select to authenticated using (true);
create policy "daily_members_lead_write" on public.daily_members for all to authenticated using (public.current_user_role() in ('ADMIN','QA_LEAD')) with check (public.current_user_role() in ('ADMIN','QA_LEAD'));
create policy "qa_generation_insert_own" on public.qa_generations for insert to authenticated with check (user_id = auth.uid());

-- Trigger propio para crear perfiles, con otro nombre
create function public.crear_perfil() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles (id, full_name) values (new.id, coalesce(new.email, 'x')); return new; end; $$;
create trigger crear_perfil_trg after insert on auth.users for each row execute function public.crear_perfil();

